from collections import OrderedDict

_MISSING = object()


class TTLCache:
    """In-memory cache whose entries expire ``ttl`` seconds after they are set."""

    def __init__(self, ttl, clock=time.monotonic, max_entries=None):
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        if max_entries is not None and max_entries < 1:
            raise ValueError("max_entries must be positive")
        self.ttl = ttl
        self._clock = clock
        self.max_entries = max_entries
        self._data = OrderedDict()

    def set(self, key, value):
        now = self._clock()
        is_new = key not in self._data

        # Only a new key can increase the number of entries.  Expired entries
        # are removed before evicting an entry when the cache is full.
        if (
            self.max_entries is not None
            and is_new
            and len(self._data) >= self.max_entries
        ):
            self._purge(now)
            while len(self._data) >= self.max_entries:
                self._data.popitem(last=False)

        self._data[key] = (now + self.ttl, value)
        # A set is a use, including when it replaces an existing value.
        self._data.move_to_end(key)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        expires, value = entry
        if expires <= self._clock():
            del self._data[key]
            return default
        # A successful get is a use.
        self._data.move_to_end(key)
        return value

    def delete(self, key):
        self._data.pop(key, None)

    def __contains__(self, key):
        # Membership checks must not change the recency order.
        entry = self._data.get(key)
        if entry is None:
            return False
        expires, _ = entry
        if expires <= self._clock():
            del self._data[key]
            return False
        return True

    def __len__(self):
        self._purge()
        return len(self._data)

    def _purge(self, now=None):
        if now is None:
            now = self._clock()
        for key in [k for k, (expires, _) in self._data.items() if expires <= now]:
            del self._data[key]

    def clear(self):
        self._data.clear()
